            if (freq[s.charAt(i) - 'a'] == 1) {
                return i;
            }
        }
        return -1;
    }
}

class Solution {
    public int firstUniqChar(String s) {
        int answer = s.length();
        for (char c = 'a'; c <= 'z'; c++) {
            int first = s.indexOf(c);
            if (first != -1 && first == s.lastIndexOf(c)) {
                answer = Math.min(answer, first);
            }
        }
        return answer == s.length() ? -1 : answer;
    }
}

import java.util.LinkedHashMap;
import java.util.Map;

class Solution {
    public int firstUniqChar(String s) {
        Map<Character, Stat> stats = new LinkedHashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            Stat stat = stats.get(c);
            if (stat == null) {
                stats.put(c, new Stat(i));
            } else {
                stat.count++;
            }
        }

        for (Stat stat : stats.values()) {
            if (stat.count == 1) {
                return stat.firstIndex;
            }
        }
        return -1;
    }

    private static class Stat {
        final int firstIndex;
        int count = 1;

        Stat(int firstIndex) {
            this.firstIndex = firstIndex;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int firstUniqChar(String s) {
        int[] freq = new int[26];
        Queue<Integer> candidates = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            int letter = s.charAt(i) - 'a';
            freq[letter]++;
            candidates.offer(i);
            while (!candidates.isEmpty() && freq[s.charAt(candidates.peek()) - 'a'] > 1) {
                candidates.poll();
            }
        }
        return candidates.isEmpty() ? -1 : candidates.peek();
    }
}

class Solution {
    public int firstUniqChar(String s) {
        Node head = new Node(-1, -1);
        Node tail = new Node(-1, -1);
        head.next = tail;
        tail.prev = head;

        Node[] active = new Node[26];
        boolean[] repeated = new boolean[26];
        for (int i = 0; i < s.length(); i++) {
            int letter = s.charAt(i) - 'a';
            if (!repeated[letter] && active[letter] == null) {
                Node node = new Node(letter, i);
                active[letter] = node;
                appendBeforeTail(tail, node);
            } else if (!repeated[letter]) {
                repeated[letter] = true;
                remove(active[letter]);
                active[letter] = null;
            }
        }

        return head.next == tail ? -1 : head.next.index;
    }

    private void appendBeforeTail(Node tail, Node node) {
        Node previous = tail.prev;
        previous.next = node;
        node.prev = previous;
        node.next = tail;
        tail.prev = node;
    }

    private void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private static class Node {
        final int letter;
        final int index;
        Node prev;
        Node next;

        Node(int letter, int index) {
            this.letter = letter;
            this.index = index;
        }
    }
}
